const API='https://yxvehbgfmabomsttmtqa.supabase.co',PUBLIC_KEY='sb_publishable_ffSNGL_BcNBiQaLUuZwD-w_GA4i9IoQ';
let session=null,org=null,refreshing=null;
async function request(path,method='GET',body,auth=true){
 if(auth&&session&&session.expires_at<Date.now()/1000+60)await refresh();
 const r=await fetch(API+path,{method,headers:{apikey:PUBLIC_KEY,...(session&&auth?{Authorization:'Bearer '+session.access_token}:{}),'Content-Type':'application/json',Prefer:'return=representation'},...(body!==undefined?{body:JSON.stringify(body)}:{})});
 const result=await r.json().catch(()=>null);if(!r.ok)throw Error(result?.msg||result?.message||result?.error_description||'Falha na conexão. Tente novamente.');return result;
}
function remember(s){session={...s,expires_at:s.expires_at||Date.now()/1000+s.expires_in};sessionStorage.setItem('agv-session',JSON.stringify(session))}
async function refresh(){if(!refreshing)refreshing=request('/auth/v1/token?grant_type=refresh_token','POST',{refresh_token:session.refresh_token},false).then(remember).catch(e=>{session=null;sessionStorage.removeItem('agv-session');throw e}).finally(()=>refreshing=null);return refreshing}
async function cloudWrite(table,row,edit=false){if(!org)throw Error('Selecione sua consultoria.');const data={id:row.id,consultancy_id:org.id,name:row.name};if(table==='clients')Object.assign(data,{contact:row.contact||'',email:row.email||''});if(table==='farms')Object.assign(data,{client_id:row.clientId,city:row.city||''});if(table==='fields')Object.assign(data,{farm_id:row.farmId,area_ha:row.area,boundary:row.rings?{type:'Polygon',coordinates:row.rings}:null});const result=await request('/rest/v1/'+table+(edit?'?id=eq.'+row.id+'&consultancy_id=eq.'+org.id:''),edit?'PATCH':'POST',data);if(!result?.length)throw Error('Cadastro não salvo. Confira suas permissões.');return result}
async function cloudDelete(table,id){const result=await request('/rest/v1/'+table+'?id=eq.'+id+'&consultancy_id=eq.'+org.id,'DELETE');if(!result?.length)throw Error('Exclusão não permitida.');}
async function loadData(){const filter=org?'&consultancy_id=eq.'+org.id:'';const rows=await Promise.all(['clients','farms','fields'].map(t=>request('/rest/v1/'+t+'?select=*&order=created_at.asc'+filter)));db={clients:rows[0],farms:rows[1].map(x=>({...x,clientId:x.client_id})),fields:rows[2].map(x=>({...x,farmId:x.farm_id,area:Number(x.area_ha),rings:x.boundary?.type==='Polygon'?x.boundary.coordinates:x.boundary?.coordinates.flat()}))};render();if(!org)$('#add').hidden=true;}
function authScreen(message=''){$('main').hidden=true;$('aside').hidden=true;let panel=document.getElementById('auth');if(!panel){panel=document.createElement('section');panel.id='auth';panel.className='auth';document.body.append(panel)}panel.innerHTML='<div class="panel"><p class="eyebrow">AGROVANTIS PRECISION</p><h1>Acesse sua consultoria</h1><p>Clientes, propriedades e talhões em um só lugar.</p><form id="login"><label>E-mail<input name="email" type="email" autocomplete="username" required></label><label>Senha<input name="password" type="password" autocomplete="current-password" minlength="8" required></label><p id="authmsg" role="status">'+esc(message)+'</p><button class="primary" name="action" value="login">Entrar</button> <button name="action" value="signup">Criar conta</button></form></div>';$('#login').onsubmit=async e=>{e.preventDefault();const form=e.target;const data=Object.fromEntries(new FormData(form));const signup=e.submitter.value==='signup';form.querySelectorAll('button').forEach(b=>b.disabled=true);try{const s=await request(signup?'/auth/v1/signup':'/auth/v1/token?grant_type=password','POST',data,false);if(!s.access_token){$('#authmsg').textContent='Confirme seu e-mail no link recebido e depois entre com sua senha.';return}remember(s);await boot()}catch(err){$('#authmsg').textContent=err.message}finally{form.querySelectorAll('button').forEach(b=>b.disabled=false)}};}
async function boot(){try{if(!session){try{session=JSON.parse(sessionStorage.getItem('agv-session'))}catch{}}if(!session){authScreen();return}const user=await request('/auth/v1/user');session.user=user;const orgs=await request('/rest/v1/consultancies?select=*&order=created_at.asc');document.getElementById('auth')?.remove();$('main').hidden=false;$('aside').hidden=false;
 const workspace=$('.workspace');workspace.innerHTML='<span>CONSULTORIA</span><select id="org" aria-label="Consultoria">'+orgs.map(o=>'<option value="'+o.id+'">'+esc(o.name)+'</option>').join('')+'</select><button id="neworg">Nova consultoria</button><button id="logout">Sair</button>';
 $('#logout').onclick=async()=>{try{await request('/auth/v1/logout','POST')}catch{}session=null;org=null;db={clients:[],farms:[],fields:[]};sessionStorage.removeItem('agv-session');authScreen()};
 $('#neworg').onclick=async()=>{const name=prompt('Nome da consultoria:','Agrovantis');if(!name?.trim())return;try{await request('/rest/v1/consultancies','POST',{name:name.trim(),owner_id:user.id});await boot()}catch(e){alert(e.message)}};
 org=orgs.find(o=>o.id===org?.id)||orgs[0]||null;$('#org').value=org?.id||'';$('#org').onchange=async e=>{org=orgs.find(o=>o.id===e.target.value);try{await loadData()}catch(err){alert(err.message)}};
 $('.notice').innerHTML=org?'Dados em nuvem · '+esc(user.email)+' <button id="reload">Atualizar</button> <button id="migrate">Copiar cadastros deste navegador</button>':'Crie sua consultoria para começar a cadastrar clientes e propriedades.';
 if(org){$('#reload').onclick=()=>loadData().catch(e=>alert(e.message));$('#migrate').onclick=migrate;}
 await loadData();
 }catch(e){authScreen(e.message)}}
async function migrate(){try{const old=JSON.parse(localStorage.getItem(KEY)||'null');if(!old||!['clients','farms','fields'].some(t=>old[t]?.length)){alert('Nenhum cadastro antigo neste navegador.');return}if(!confirm('Copiar os cadastros antigos para '+org.name+'? Os dados locais serão preservados.'))return;$('#migrate').disabled=true;for(const t of ['clients','farms','fields'])for(const row of old[t]||[]){if(db[t].some(x=>x.id===row.id))continue;await cloudWrite(t,row);await loadData()}alert('Cadastros copiados para a nuvem.')}catch(e){alert('Cópia interrompida: '+e.message+'. Você pode tentar novamente.')}finally{if($('#migrate'))$('#migrate').disabled=false}}
